"use client";
import {ArtemisScope} from "./artemis-scope";
import View1 from "./components/sidebar/variants/02-workspace";
const views={"workspace":View1};
export interface ArtemisSidebarProps {className?:string;variant?:"workspace";}
export function ArtemisSidebar({className,variant="workspace"}:ArtemisSidebarProps){const View=views[variant];return <ArtemisScope className={className}><View/></ArtemisScope>;}

// @zeus-internal
const GUARD_ATTRIBUTE = "data-radix-focus-guard";
const MARKER_ATTRIBUTE = "data-aria-hidden";
const LOCK_ATTRIBUTE = "data-scroll-locked";
let guardCount = 0;
function createFocusGuard(): HTMLSpanElement {
    const guard = document.createElement("span");
    guard.setAttribute(GUARD_ATTRIBUTE, "");
    guard.tabIndex = 0;
    guard.style.outline = "none";
    guard.style.opacity = "0";
    guard.style.position = "fixed";
    guard.style.pointerEvents = "none";
    return guard;
}
export function acquireFocusGuards(): () => void {
    const existing = document.querySelectorAll(`[${GUARD_ATTRIBUTE}]`);
    document.body.insertAdjacentElement("afterbegin", existing[0] ?? createFocusGuard());
    document.body.insertAdjacentElement("beforeend", existing[1] ?? createFocusGuard());
    guardCount += 1;
    return () => {
        if (guardCount === 1) {
            for (const node of Array.from(document.querySelectorAll(`[${GUARD_ATTRIBUTE}]`)))
                node.remove();
        }
        guardCount -= 1;
    };
}
const hiddenCount = new WeakMap<Element, number>();
const markerCount = new WeakMap<Element, number>();
const alreadyHiddenNodes = new WeakSet<Element>();
export function hideOthers(target: Element): () => void {
    const body = target.ownerDocument.body;
    const targets: Element[] = [target, ...Array.from(body.querySelectorAll("[aria-live], script"))];
    const stop = new Set<Element>(targets);
    const keep = new Set<Node>();
    const keepWithAncestors = (node: Node | null) => {
        if (!node || keep.has(node))
            return;
        keep.add(node);
        keepWithAncestors(node.parentNode);
    };
    for (const node of targets)
        keepWithAncestors(node);
    const hidden: Element[] = [];
    const walk = (parent: Element) => {
        if (stop.has(parent))
            return;
        for (const node of Array.from(parent.children)) {
            if (keep.has(node)) {
                walk(node);
                continue;
            }
            const attribute = node.getAttribute("aria-hidden");
            const wasHidden = attribute !== null && attribute !== "false";
            const count = (hiddenCount.get(node) ?? 0) + 1;
            const markers = (markerCount.get(node) ?? 0) + 1;
            hiddenCount.set(node, count);
            markerCount.set(node, markers);
            hidden.push(node);
            if (count === 1 && wasHidden)
                alreadyHiddenNodes.add(node);
            if (markers === 1)
                node.setAttribute(MARKER_ATTRIBUTE, "true");
            if (!wasHidden)
                node.setAttribute("aria-hidden", "true");
        }
    };
    walk(body);
    return () => {
        for (const node of hidden) {
            const count = (hiddenCount.get(node) ?? 1) - 1;
            const markers = (markerCount.get(node) ?? 1) - 1;
            hiddenCount.set(node, count);
            markerCount.set(node, markers);
            if (count === 0) {
                if (!alreadyHiddenNodes.has(node))
                    node.removeAttribute("aria-hidden");
                alreadyHiddenNodes.delete(node);
            }
            if (markers === 0)
                node.removeAttribute(MARKER_ATTRIBUTE);
        }
    };
}
let lockCount = 0;
let lockStyle: HTMLStyleElement | null = null;
function px(value: string): number {
    const parsed = Number.parseInt(value, 10);
    return Number.isFinite(parsed) ? parsed : 0;
}
function lockCss(): string {
    const computed = window.getComputedStyle(document.body);
    const left = px(computed.marginLeft);
    const top = px(computed.marginTop);
    const right = px(computed.marginRight);
    const gap = Math.max(0, window.innerWidth - document.documentElement.clientWidth + right - left);
    return `
  .with-scroll-bars-hidden {
   overflow: hidden !important;
   padding-right: ${gap}px !important;
  }
  body[${LOCK_ATTRIBUTE}] {
    overflow: hidden !important;
    overscroll-behavior: contain;
    position: relative !important;
    padding-left: ${left}px;
    padding-top: ${top}px;
    padding-right: ${right}px;
    margin-left:0;
    margin-top:0;
    margin-right: ${gap}px !important;
  }
  body[${LOCK_ATTRIBUTE}] {
    --removed-body-scroll-bar-size: ${gap}px;
  }
`;
}
export function lockBodyScroll(): () => void {
    if (lockCount === 0) {
        lockStyle = document.createElement("style");
        lockStyle.textContent = lockCss();
        document.head.appendChild(lockStyle);
    }
    lockCount += 1;
    document.body.setAttribute(LOCK_ATTRIBUTE, String(lockCount));
    return () => {
        lockCount -= 1;
        if (lockCount > 0) {
            document.body.setAttribute(LOCK_ATTRIBUTE, String(lockCount));
            return;
        }
        document.body.removeAttribute(LOCK_ATTRIBUTE);
        lockStyle?.remove();
        lockStyle = null;
    };
}

"use client";
import {useArtemisContainerMobile} from "../../../lib/use-container-mobile";
// @zeus-internal
import { useEffect, useRef, useState, type CSSProperties } from "react";
import { artemisCreatePortal } from "../../../artemis-scope";
import { motion, useReducedMotion } from "motion/react";
import { PANEL_TRANSITION, REDUCED_TRANSITION, SIDEBAR_MORPH_TRANSITION } from "./02-workspace/transitions";
import { WorkspacePanel } from "./02-workspace/panel";
export default function SidebarWorkspace() {
    const reduce = useReducedMotion();
    const drawerRef = useRef<HTMLDivElement>(null);
    const mobileOpenRef = useRef(false);
    const [collapsed, setCollapsed] = useState(false);
    const [containerRef,mobile] = useArtemisContainerMobile();
    useEffect(() => { if (!mobile) setMobileOpen(false); }, [mobile]);
    const [mobileOpen, setMobileOpen] = useState(false);
    const [drawerVisible, setDrawerVisible] = useState(false);
    const [selected, setSelected] = useState("Overview");
    const [workspace, setWorkspace] = useState("Workspace AI");
    const triggerRef = useRef<HTMLButtonElement>(null);
    useEffect(() => {
        mobileOpenRef.current = mobileOpen;
        if (mobileOpen)
            setDrawerVisible(true);
    }, [mobileOpen]);
    useEffect(() => {
        if (!mobileOpen)
            return;
        const body = document.body;
        const scrollY = window.scrollY;
        const previous = { left: body.style.left, overflow: body.style.overflow, position: body.style.position, right: body.style.right, top: body.style.top };
        body.style.position = "fixed";
        body.style.top = `-${scrollY}px`;
        body.style.left = "0";
        body.style.right = "0";
        body.style.overflow = "hidden";
        const frame = requestAnimationFrame(() => {
            const first = drawerRef.current?.querySelector<HTMLElement>("a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex=\"-1\"])");
            (first ?? drawerRef.current)?.focus({ preventScroll: true });
        });
        return () => {
            cancelAnimationFrame(frame);
            Object.assign(body.style, previous);
            window.scrollTo(0, scrollY);
            triggerRef.current?.focus({ preventScroll: true });
        };
    }, [mobileOpen]);
    useEffect(() => {
        if (!mobileOpen)
            return;
        const escape = (event: KeyboardEvent) => { if (event.key === "Escape" && !event.defaultPrevented && !document.querySelector('[role="dialog"][aria-label="Search"]')) {
            event.preventDefault();
            closeMobile();
        } };
        window.addEventListener("keydown", escape);
        return () => window.removeEventListener("keydown", escape);
    }, [mobileOpen]);
    useEffect(() => {
        const shortcut = (event: KeyboardEvent) => {
            if (event.key.toLowerCase() !== "b" || !(event.ctrlKey || event.metaKey))
                return;
            event.preventDefault();
            if (mobile)
                setMobileOpen(open => !open);
            else
                setCollapsed(value => !value);
        };
        window.addEventListener("keydown", shortcut);
        return () => window.removeEventListener("keydown", shortcut);
    }, [mobile]);
    const closeMobile = () => { setMobileOpen(false); triggerRef.current?.focus(); };
    const toggle = () => mobile ? setMobileOpen(open => !open) : setCollapsed(value => !value);
    const select = (name: string) => { setSelected(name); if (mobile)
        closeMobile(); };
    const state = collapsed ? "collapsed" : "expanded";
    return (<>
      <>
        <div ref={containerRef} data-slot="sidebar-wrapper" data-state={state} style={{ "--artemis-sidebar-width": "16rem", "--artemis-sidebar-width-icon": "4.25rem", "--artemis-sidebar-width-mobile": "18rem" } as CSSProperties} className="art:group/sidebar-wrapper art:flex art:w-full art:min-w-0 art:h-[720px] art:min-h-0 art:overflow-hidden art:rounded-2xl art:border art:border-foreground/[0.08] art:bg-background">
          {!mobile && <motion.aside aria-label={`${workspace} workspace`} data-slot="sidebar" data-state={state} data-collapsible="icon" data-variant="sidebar" data-side="left" className="art:group/sidebar art:relative art:hidden art:h-auto art:shrink-0 art:@min-[768px]/artemis:block art:will-change-[width] art:peer art:min-h-0" initial={false} animate={{ width: collapsed ? "var(--artemis-sidebar-width-icon)" : "var(--artemis-sidebar-width)" }} transition={reduce ? { duration: 0 } : SIDEBAR_MORPH_TRANSITION}>
            <WorkspacePanel collapsed={collapsed} mobile={false} selected={selected} workspace={workspace} onSelect={select} onWorkspace={setWorkspace} onClose={closeMobile} onExpand={() => setCollapsed(false)}/>
          </motion.aside>}
          <main data-slot="sidebar-inset" className="art:relative art:flex art:min-w-0 art:flex-1 art:flex-col art:@min-[768px]/artemis:peer-data-[variant=inset]:m-2 art:@min-[768px]/artemis:peer-data-[variant=inset]:ml-0 art:@min-[768px]/artemis:peer-data-[variant=inset]:rounded-2xl art:@min-[768px]/artemis:peer-data-[variant=inset]:shadow-sm art:min-h-0 art:bg-background">
            <header className="art:flex art:h-16 art:shrink-0 art:items-center art:gap-3 art:border-border art:border-b art:px-4">
              <button ref={triggerRef} type="button" aria-label="Toggle sidebar" aria-expanded={mobile ? mobileOpen : !collapsed} data-slot="sidebar-trigger" data-state={mobile ? mobileOpen ? "expanded" : "collapsed" : state} onClick={toggle} className="art:inline-flex art:size-10 art:shrink-0 art:items-center art:justify-center art:rounded-xl art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:text-muted-foreground art:transition-colors art:hover:bg-muted art:hover:text-foreground">
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-panel-left art:size-4" aria-hidden="true">
                  <rect width="18" height="18" x="3" y="3" rx="2"/>
                  <path d="M9 3v18"/>
                </svg>
              </button>
              <div className="art:h-5 art:w-px art:bg-border"/>
              <p className="art:font-medium art:text-foreground art:text-sm">
                {selected}
              </p>
            </header>
            <div className="art:flex art:min-h-0 art:flex-1 art:flex-col art:justify-between art:overflow-hidden art:p-5 art:@min-[640px]/artemis:p-7">
              <div>
                <p className="art:font-medium art:text-muted-foreground art:text-xs">
                  {"Live workspace"}
                </p>
                <h3 className="art:mt-2 art:max-w-md art:tracking-tight art:text-xl art:font-medium">
                  {"Good morning, Alex."}
                </h3>
                <p className="art:mt-2 art:max-w-md art:text-muted-foreground art:text-sm art:leading-6">
                  {"Your workspace stays in place while the navigation folds into a focused icon rail."}
                </p>
              </div>
              <div className="art:grid art:gap-3 art:@min-[640px]/artemis:grid-cols-3">
                <div className="art:rounded-xl art:border art:border-border art:p-4">
                  <p className="art:text-muted-foreground art:text-xs">
                    {"Runs"}
                  </p>
                  <p className="art:mt-4 art:font-semibold art:text-xl">
                    {"1,284"}
                  </p>
                </div>
                <div className="art:rounded-xl art:border art:border-border art:p-4">
                  <p className="art:text-muted-foreground art:text-xs">
                    {"Success rate"}
                  </p>
                  <p className="art:mt-4 art:font-semibold art:text-xl">
                    {"98.4%"}
                  </p>
                </div>
                <div className="art:rounded-xl art:border art:border-border art:p-4">
                  <p className="art:text-muted-foreground art:text-xs">
                    {"Time saved"}
                  </p>
                  <p className="art:mt-4 art:font-semibold art:text-xl">
                    {"42h"}
                  </p>
                </div>
              </div>
            </div>
          </main>
        </div>
      </>
      {mobile && typeof document !== "undefined" && artemisCreatePortal(<div className={`art:pointer-events-none art:fixed art:left-0 art:top-0 art:z-50 art:size-0 art:@min-[768px]/artemis:hidden ${drawerVisible || mobileOpen ? "art:visible" : "art:invisible"}`}>
        <motion.button type="button" aria-label="Close sidebar" tabIndex={mobileOpen ? 0 : -1} className={`art:fixed art:inset-0 art:bg-black/40 ${mobileOpen ? "art:pointer-events-auto" : "art:pointer-events-none"}`} initial={false} animate={{ opacity: mobileOpen ? 1 : 0 }} transition={reduce ? REDUCED_TRANSITION : PANEL_TRANSITION} onClick={closeMobile}/>
        <motion.div ref={drawerRef} role="dialog" aria-modal="true" aria-label={`${workspace} workspace`} aria-hidden={!mobileOpen} inert={!mobileOpen ? true : undefined} tabIndex={-1} data-mobile="true" data-state={mobileOpen ? "expanded" : "collapsed"} data-side="left" className={`${mobileOpen ? "art:pointer-events-auto" : "art:pointer-events-none"} art:fixed art:inset-y-0 art:flex art:h-dvh art:w-72 art:max-w-[88vw] art:flex-col art:overflow-hidden art:border-border art:bg-background art:shadow-2xl art:will-change-transform art:left-0 art:border-r art:min-h-0`} initial={false} animate={{ opacity: reduce ? mobileOpen ? 1 : 0 : 1, x: reduce ? 0 : mobileOpen ? "0%" : "-100%" }} onAnimationComplete={() => { if (!mobileOpenRef.current)
            setDrawerVisible(false); }} onKeyDown={event => {
                if (event.key !== "Tab")
                    return;
                const focusable = Array.from(drawerRef.current?.querySelectorAll<HTMLElement>("a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex=\"-1\"])") ?? []);
                if (!focusable.length) {
                    event.preventDefault();
                    drawerRef.current?.focus();
                    return;
                }
                if (event.shiftKey && document.activeElement === focusable[0]) {
                    event.preventDefault();
                    focusable.at(-1)?.focus();
                }
                else if (!event.shiftKey && document.activeElement === focusable.at(-1)) {
                    event.preventDefault();
                    focusable[0]?.focus();
                }
            }} transition={reduce ? REDUCED_TRANSITION : PANEL_TRANSITION}>
          <WorkspacePanel collapsed={false} mobile selected={selected} workspace={workspace} onSelect={select} onWorkspace={setWorkspace} onClose={closeMobile}/>
        </motion.div>
      </div>, document.body)}
    </>);
}

