"use client";
// @zeus-internal
import { animate, motion, useMotionValue, useReducedMotion } from "motion/react";
import { useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { ARTEMIS_SPRING_LAYOUT } from "../../../../lib/ease";
export function GroupChevron({ expanded, collapsed, primed, activationKey, children }: {
    expanded: boolean;
    collapsed: boolean;
    primed: boolean;
    activationKey: string;
    children: ReactNode;
}) {
    const reduce = useReducedMotion();
    const angle = useMotionValue(expanded ? 90 : 0);
    const x = useMotionValue(collapsed ? 4 : 0);
    const previous = useRef({ expanded, collapsed, activationKey });
    const [activated, setActivated] = useState(primed);
    useLayoutEffect(() => {
        const primeChanged = (!activated && primed) || previous.current.activationKey !== activationKey;
        if (previous.current.expanded === expanded && previous.current.collapsed === collapsed && !primeChanged)
            return;
        const expandedChanged = previous.current.expanded !== expanded;
        previous.current = { expanded, collapsed, activationKey };
        let frame = 0;
        if (!activated && !expandedChanged && !reduce && !primeChanged)
            frame = requestAnimationFrame(() => setActivated(true));
        else
            setActivated(true);
        const transition = reduce ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT;
        const controls = [animate(x, !reduce && collapsed ? 4 : 0, transition)];
        if (expandedChanged)
            controls.push(animate(angle, expanded ? 90 : 0, transition));
        return () => { cancelAnimationFrame(frame); controls.forEach(control => control.stop()); };
    }, [expanded, collapsed, primed, activationKey, reduce, angle, x]);
    return <motion.span initial={false} animate={{ opacity: collapsed ? 0 : 1 }} transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_LAYOUT} aria-hidden="true" className="art:relative art:z-10 art:grid art:size-4 art:shrink-0 art:place-items-center art:text-muted-foreground" style={{ x, rotate: activated ? angle : 0 }}>{children}</motion.span>;
}

