export const pages = [{ name: "Overview", group: "Workspace", icon: CircleGauge }, { name: "Agents", group: "Workspace", icon: Bot, count: "6", children: ["All agents", "Playground", "Evaluations"] }, { name: "Workflows", group: "Workspace", icon: GitBranch, children: ["Automations", "Run history", "Templates"] }, { name: "Knowledge", group: "Workspace", icon: FileText }, { name: "Integrations", group: "Workspace", icon: Boxes }, { name: "Analytics", group: "Workspace", icon: ChartNoAxesCombined }, { name: "Members", group: "Workspace", icon: Users }, { name: "API keys", group: "Workspace", icon: KeyRound }, { name: "Settings", group: "Workspace", icon: Settings }] as const;
export function WorkspaceNavigation({ primed, activationKey, ...props }: {
    selected: string;
    collapsed: boolean;
    primed: boolean;
    activationKey: string;
    onSelect: (name: string) => void;
    onExpand?: () => void;
}) { return <ArtemisSidebarNavigation {...props} pages={pages} label="Workspace" chevron={expanded => <GroupChevron expanded={expanded} collapsed={props.collapsed} primed={primed} activationKey={activationKey}><ChevronRight className="art:size-3.5"/></GroupChevron>}/>; }

"use client";
// @zeus-internal
import { useCallback, useId, useRef, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { ARTEMIS_SPRING_LAYOUT, ARTEMIS_SPRING_PRESS } from "../../../../lib/ease";
