      const bounds = element.getBoundingClientRect();
      if (!bounds.width) return;
      const css = getComputedStyle(element), width = Number.parseFloat(css.width);
      setMobile((css.boxSizing === "border-box" && Number.isFinite(width) ? width : element.offsetWidth) < breakpoint);
