    previous.current = open;
    if (opening) start();
  }, [open, start]);
}

"use client";
// @zeus-internal
import { useCallback, useLayoutEffect, useRef, useState } from "react";
interface Cursor { key: string; session: string; }
export function useArtemisRowCursor(rows: readonly { id: string }[], query: string) {
  const [selection, select] = useState<Cursor | null>(null);
  const committed = useRef({ rows, query });
  const index = selection?.session === query ? rows.findIndex(row => row.id === selection.key) : -1;
  useLayoutEffect(() => {
    committed.current = { rows, query };
    if (selection && index < 0) select(null);
  }, [rows, query, selection, index]);
  const moveTo = useCallback((id: string | null) => {
    select(id === null ? null : { key: id, session: committed.current.query });
  }, []);
  const moveActive = useCallback((direction: 1 | -1) => {
    select(previous => {
      const { rows: choices, query: session } = committed.current;
      if (!choices.length) return previous;
      const position = previous?.session === session ? choices.findIndex(row => row.id === previous.key) : -1;
      const next = Math.max(0, Math.min(choices.length - 1, Math.max(0, position) + direction));
